/**
 * Move animation wiring (owner order 2026-10-29): every move in MOVES_DB
 * resolves — by its STABLE internal id, never by display name — to a
 * per-move animation profile in src/lib/generated/moveAnimationRegistry.json
 * (generated by move-animation-wiring/tools/generate_registry.py from
 * moves.ts + the batch-2 catalogue + decomp provenance + the union move
 * scripts). A profile carries the animation GRAMMAR of the Pokémon move
 * the game move was built from: delivery, canonical timeline, impact,
 * trail, camera, sound cue, palette, and per-performer-class anatomy
 * variance. Profiles are native parameterisations (our own primitives);
 * no donor assets are used.
 *
 * Before this module, BattleView/PixiBattleCanvas resolved presentation
 * from CATEGORY alone (Physical = the same lunge, Special = one coloured
 * dot, Status = a pulse) plus per-creature attack art — so Tackle and
 * Swift Movement (Quick Attack) rendered identically. The coverage test
 * (moveAnimation.test.ts) fails if any MOVES_DB move ever resolves to a
 * generic fallback again.
 */
import registryData from "./generated/moveAnimationRegistry.json";
import poolData from "./generated/fullMovePool.json";
import { MOVES_DB } from "./moves";

export type MoveDelivery =
  | "contact_lunge" | "blitz_afterimage" | "projectile" | "beam" | "spread"
  | "multi_hit" | "field_impact" | "self_aura" | "status_gaze" | "status_cloud"
  | "charge_release" | "drain_link" | "protect_wall";

export interface MoveAnimationProfile {
  delivery: MoveDelivery;
  timelineMs: { windup: number; travel: number; impactHold: number; recoil: number; recover: number; total: number };
  phaseFractions: { travelComplete: number; impactAt: number };
  impact: {
    amplitudePx: number;
    shake: "soft" | "light" | "heavy" | "quake";
    flash: string;
    particleKind: string;
    particleCount: number;
    burstCount: number;
    statusPuff: string | null;
    beats: number;
    hitCount: { min: number; max: number } | null;
  };
  trail: { kind: string; afterimages: number } | null;
  projectileShape: string | null;
  camera: string;
  soundCue: string;
  targetReaction: string;
  palette: string;
  anatomyVariance: Record<PerformerClass, string>;
  signature: string;
}

export type PerformerClass = "standard" | "heavy" | "small" | "hover" | "rooted";

export interface MoveAnimationEntry {
  id: string;
  displayName: string;
  sourcePokemonMove: string | null;
  sourceBasis: string;
  legacyAnimField: string;
  type: string;
  category: string;
  power: number;
  effect: string;
  categoryAdaptation: string | null;
  profile: MoveAnimationProfile;
}

const REGISTRY = registryData as unknown as {
  version: string;
  moveCount: number;
  moves: MoveAnimationEntry[];
};

export const MOVE_ANIMATION_REGISTRY_VERSION = REGISTRY.version;

const BY_ID = new Map<string, MoveAnimationEntry>(REGISTRY.moves.map((m) => [m.id, m]));

/**
 * FULL MOVE POOL (batch 3, owner order 2026-10-29): every Pokemon move —
 * 919 rows in src/lib/generated/fullMovePool.json — carries an animation
 * profile in the same 13-family grammar (script-union parameterised where
 * a decomp script exists, composed from its effect class where not). The
 * resolver falls back to the pool so ANY move id the game can reference —
 * a live MOVES_DB id or a pool id — resolves to a per-move profile, never
 * to a generic fallback.
 */
interface PoolRow {
  id: string;
  displayNameDraft: string;
  type: string;
  category: string;
  power: number;
  effect: string | null;
  profileProvenance: string;
  profile: MoveAnimationProfile;
}
const POOL = poolData as unknown as { poolCount: number; moves: PoolRow[] };
export const FULL_MOVE_POOL_COUNT = POOL.poolCount;
const POOL_BY_ID = new Map<string, MoveAnimationEntry>(
  POOL.moves.map((r) => [r.id, {
    id: r.id,
    displayName: r.displayNameDraft,
    sourcePokemonMove: r.id,
    sourceBasis: r.profileProvenance,
    legacyAnimField: r.id,
    type: r.type,
    category: r.category,
    power: r.power,
    effect: r.effect ?? "NONE",
    categoryAdaptation: null,
    profile: r.profile,
  }]),
);

/** The one resolver the battle path uses. Null only for an unknown id. */
export function getMoveAnimation(moveId: string | undefined | null): MoveAnimationEntry | null {
  if (!moveId) return null;
  return BY_ID.get(moveId) ?? POOL_BY_ID.get(moveId) ?? null;
}

export function getMoveAnimationProfile(moveId: string | undefined | null): MoveAnimationProfile | null {
  return getMoveAnimation(moveId)?.profile ?? null;
}

/**
 * Groups whose members share ONE profile signature legitimately: two game
 * data rows built from the SAME Pokémon move (the source games have a
 * single animation for that move). Any other signature collision is a
 * coverage failure — see the test.
 */
export const JUSTIFIED_IDENTICAL_GROUPS: string[][] = [
  ["AQUA_SHOT", "TIDE_SHOT"],        // both built from WATER_GUN
  ["DARK_PULSE_MOVE", "UMBRAL_PULSE"], // both DARK_PULSE
  ["DRILL_BEAK", "WING_ASSAULT"],    // both DRILL_PECK
  ["EMBER_FLICK", "EMBER_TOSS"],     // both EMBER
  ["GUST_WAVE", "WIND_GUST"],        // both GUST
  ["IRON_CLAW", "METAL_STRIKE"],     // both METAL_CLAW
  ["LEAF_WHIP", "VINE_LASH"],        // both VINE_WHIP
  ["POWER_STRIKE", "SKY_KICK"],      // both SKY_UPPERCUT
  ["SHADOW_PULSE", "UMBRAL_ORB"],    // both SHADOW_BALL
  ["SPARK_SHOT", "STATIC_JOLT"],     // both THUNDER_SHOCK
];

/** Performer class from the creature registry's idle class (creatureAnimation.ts IDLE). */
export function performerClassForIdle(idleClass: string | undefined | null): PerformerClass {
  switch (idleClass) {
    case "heavy_slow": return "heavy";
    case "small_bouncy": return "small";
    case "hover_swim": case "float_hover": return "hover";
    case "seated": case "static_crystal": return "rooted";
    default: return "standard";
  }
}

/**
 * Coverage audit, run by the test and available to tooling: every live
 * move must have a profile, no profile may be the generic fallback, and
 * no two moves may share a rendered signature outside the justified
 * same-source groups.
 */
export function validateMoveAnimationCoverage(): string[] {
  const problems: string[] = [];
  for (const id of Object.keys(MOVES_DB)) {
    const entry = BY_ID.get(id) ?? POOL_BY_ID.get(id);
    if (!entry) { problems.push(`${id}: no animation profile`); continue; }
    const p = entry.profile;
    if (!p || !p.delivery || !p.signature) problems.push(`${id}: profile is a generic fallback`);
    if (p && p.timelineMs.total <= 0) problems.push(`${id}: empty timeline`);
  }
  const justified = new Set(JUSTIFIED_IDENTICAL_GROUPS.map((g) => [...g].sort().join("+")));
  const bySig = new Map<string, string[]>();
  for (const m of REGISTRY.moves) {
    const arr = bySig.get(m.profile.signature) ?? [];
    arr.push(m.id);
    bySig.set(m.profile.signature, arr);
  }
  for (const ids of bySig.values()) {
    if (ids.length > 1 && !justified.has([...ids].sort().join("+"))) {
      problems.push(`${ids.join(", ")}: shared profile signature outside the justified same-source groups`);
    }
  }
  return problems;
}

/**
 * Full-pool coverage audit (batch 3): every pool row must be complete
 * (stats + machine data fields + a non-generic profile), every pool id
 * and every MOVES_DB id must resolve, and the pool must never drop below
 * the Gen-5 floor of 559 moves.
 */
export function validateFullMovePoolCoverage(): string[] {
  const problems: string[] = [];
  if (POOL.moves.length < 559) {
    problems.push(`pool below Gen-5 floor: ${POOL.moves.length} < 559`);
  }
  const seen = new Set<string>();
  for (const r of POOL.moves) {
    if (seen.has(r.id)) problems.push(`${r.id}: duplicate pool id`);
    seen.add(r.id);
    if (!r.type || !r.category) problems.push(`${r.id}: missing type/category`);
    if (!r.profile || !r.profile.delivery || !r.profile.signature) {
      problems.push(`${r.id}: profile is a generic fallback`);
    }
    if (!POOL_BY_ID.has(r.id)) problems.push(`${r.id}: does not resolve`);
  }
  for (const id of Object.keys(MOVES_DB)) {
    if (!getMoveAnimation(id)) problems.push(`${id}: live move does not resolve`);
  }
  return problems;
}
